package cl.bolsillo.app;
import android.content.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
import static cl.bolsillo.app.Forms.*;

final class Extras {
 static void reports(MainActivity a)throws Exception{Form f=new Form(a,"Informe · "+a.month);f.note("Selecciona otro mes desde Actividad o Plan.");long income=Ledger.flow(a.data,a.month,"income",""),expense=Ledger.flow(a.data,a.month,"expense","");f.note("Ingresos "+a.money(income)+"\nGastos "+a.money(expense)+"\nResultado "+a.money(income-expense));JSONArray cats=a.data.getJSONArray("categories");for(int i=0;i<cats.length();i++){JSONObject c=cats.getJSONObject(i);if(!c.optString("type").equals("expense"))continue;long n=Ledger.flow(a.data,a.month,"expense",c.getString("id"));if(n>0){f.note(c.getString("name")+" · "+a.money(n)+" · "+(expense==0?0:Math.round(100.0*n/expense))+"%");ProgressBar bar=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);bar.setProgress(expense==0?0:(int)(100.0*n/expense));f.box.addView(bar);}}f.note("Evolución de los últimos 6 meses");for(int j=5;j>=0;j--){String m=java.time.LocalDate.parse(a.month+"-01").minusMonths(j).toString().substring(0,7);f.note(m+" · ingresos "+a.money(Ledger.flow(a.data,m,"income",""))+" · gastos "+a.money(Ledger.flow(a.data,m,"expense","")));}f.save("Cerrar informe",()->{});}
 static void categories(MainActivity a)throws Exception{Form f=new Form(a,"Categorías");JSONArray list=a.data.getJSONArray("categories");for(int i=0;i<list.length();i++){JSONObject c=list.getJSONObject(i);f.action(c.getString("name")+" · "+(c.optBoolean("archived")?"archivada":c.getString("type").equals("expense")?"gasto":"ingreso"),()->{Form e=new Form(a,"Editar categoría");EditText name=e.field("Nombre",c.getString("name"),false);Switch archived=e.toggle("Archivar",c.optBoolean("archived"));e.save("Guardar",()->{LocalData.change(a,d->{String clean=value(name),normalized=ConceptCatalog.normalize(clean);Ledger.require(clean.length()>=2&&clean.length()<=50,"La categoría debe tener entre 2 y 50 caracteres");JSONArray current=d.getJSONArray("categories");for(int j=0;j<current.length();j++){JSONObject other=current.getJSONObject(j);Ledger.require(other.getString("id").equals(c.getString("id"))||!other.optString("type").equals(c.optString("type"))||!ConceptCatalog.normalize(other.optString("name")).equals(normalized),"Ya existe una categoría con ese nombre");}JSONObject target=Ledger.find(current,c.getString("id"));target.put("name",clean).put("archived",archived.isChecked());});f.dialog.dismiss();});});}EditText name=f.field("Nueva categoría","",false);Spinner type=f.select("Tipo",Arrays.asList("Gasto","Ingreso"),0);f.save("Crear categoría",()->LocalData.change(a,d->ConceptCatalog.ensureCategory(d,type.getSelectedItemPosition()==0?"expense":"income",value(name))));}
 static void shared(MainActivity a)throws Exception{Form f=new Form(a,"Gastos compartidos");JSONArray txs=a.data.getJSONArray("transactions");int count=0;for(int i=0;i<txs.length();i++){JSONObject t=txs.getJSONObject(i);JSONArray shares=t.optJSONArray("shares");if(!t.optString("status").equals("posted")||t.optString("date").compareTo(Ledger.today())>0||shares==null)continue;for(int j=0;j<shares.length();j++){JSONObject s=shares.getJSONObject(j);String claim=t.getString("id")+":"+s.getString("id");long paid=0;for(int k=0;k<txs.length();k++){JSONObject p=txs.getJSONObject(k);if(p.optString("type").equals("repayment")&&p.optString("receivable").equals(claim))paid+=p.getLong("amount");}long remaining=s.getLong("amount")-paid;if(remaining<=0)continue;count++;f.action(s.getString("name")+" · "+a.money(remaining),()->{Form pay=new Form(a,"Registrar cobro");EditText amt=pay.field("Monto recibido",String.valueOf(remaining),true);Pick account=new Pick(pay,"Cuenta que recibió el dinero","accounts","",t.getString("account"));pay.save("Guardar cobro",()->{JSONObject receipt=NativeSync.transaction("repayment",amount(amt,false),account.id(),"","","Cobro de "+s.getString("name"),"manual","");receipt.put("receivable",claim);LocalData.upsert(a,"transactions",receipt);f.dialog.dismiss();});});}}if(count==0)f.note("No tienes cobros pendientes. Al crear un gasto puedes indicar quién comparte el pago y cuánto te debe.");f.note("Los cobros devuelven dinero a tu cuenta y no se cuentan como nuevos ingresos. Cobros pendientes o futuros reservan su parte para evitar cobrar de más.");f.save("Cerrar",()->{});}
 static void templates(MainActivity a)throws Exception{Form f=new Form(a,"Plantillas");JSONArray list=a.data.getJSONArray("templates");for(int i=0;i<list.length();i++){JSONObject t=list.getJSONObject(i);f.action(t.getString("name")+" · "+a.money(t.getLong("amount")),()->NativeSettings.choose(a,"Plantilla",Arrays.asList("Registrar con esta plantilla","Eliminar plantilla"),n->a.attempt(()->{if(n==1){LocalData.remove(a,"templates",t.getString("id"));f.dialog.dismiss();return;}JSONObject tx=NativeSync.transaction(t.getString("type"),t.getLong("amount"),t.getString("account"),"",t.getString("category"),t.getString("name"),"manual","");Forms.transaction(a,tx,t.getString("type"));})));}f.action("Crear plantilla",()->NativeSettings.choose(a,"Tipo",Arrays.asList("Gasto","Ingreso"),type->a.attempt(()->{String kind=type==0?"expense":"income";Form n=new Form(a,"Nueva plantilla");EditText name=n.field("Nombre","",false),amt=n.field("Monto","",true);Pick account=new Pick(n,"Cuenta","accounts","",""),category=new Pick(n,"Categoría","categories",kind,"");n.save("Guardar plantilla",()->{Ledger.require(!value(name).isEmpty(),"Falta nombre");LocalData.upsert(a,"templates",new JSONObject().put("id",Ledger.id()).put("name",value(name)).put("type",kind).put("amount",amount(amt,false)).put("account",account.id()).put("category",category.id()));f.dialog.dismiss();});})));f.save("Cerrar",()->{});}
 static void groups(MainActivity a)throws Exception{Form f=new Form(a,"Grupos de cuentas");Map<String,Long> balances=Ledger.balances(a.data,Ledger.today());JSONArray groups=a.data.getJSONArray("groups");for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);long sum=0;JSONArray ids=g.getJSONArray("accounts");for(int j=0;j<ids.length();j++)sum+=balances.getOrDefault(ids.getString(j),0L);f.action(g.getString("name")+" · "+a.money(sum),()->a.confirm("Eliminar grupo","Las cuentas se conservan.",()->{LocalData.remove(a,"groups",g.getString("id"));f.dialog.dismiss();}));}EditText name=f.field("Nombre del nuevo grupo","",false);JSONArray accounts=a.data.getJSONArray("accounts");List<CheckBox> checks=new ArrayList<>();for(int i=0;i<accounts.length();i++){CheckBox check=new CheckBox(a);Controls.style(check);check.setText(accounts.getJSONObject(i).getString("name"));f.box.addView(check);checks.add(check);}f.save("Crear grupo",()->{Ledger.require(!value(name).isEmpty(),"Falta nombre");JSONArray ids=new JSONArray();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked())ids.put(accounts.getJSONObject(i).getString("id"));Ledger.require(ids.length()>0,"Elige al menos una cuenta");LocalData.upsert(a,"groups",new JSONObject().put("id",Ledger.id()).put("name",value(name)).put("accounts",ids));});}
 static void yield(MainActivity host,JSONObject a)throws Exception{Form f=new Form(host,"Rendimientos · "+a.getString("name"));JSONObject old=a.optJSONObject("yield");EditText rate=f.field("Tasa anual estimada (%)",old==null?"0":old.optString("annualRate","0"),false);long balance=Ledger.balances(host.data,Ledger.today()).get(a.getString("id"));f.note("La tasa la configuras tú. La proyección no cambia el saldo: registra solo intereses que el banco haya abonado.");f.action("Calcular proyección anual simple",()->{double r=Double.parseDouble(value(rate).replace(',','.'));Ledger.require(Double.isFinite(r)&&r>=0&&r<=200,"Tasa inválida");NativeSettings.info(host,"Estimación simple a saldo constante: "+host.money(Math.round(Math.max(0,balance)*r/100))+" al año, antes de impuestos");});EditText earned=f.field("Interés realmente abonado (0 para solo guardar tasa)","0",true);f.save("Guardar",()->{double r=Double.parseDouble(value(rate).replace(',','.'));Ledger.require(Double.isFinite(r)&&r>=0&&r<=200,"Tasa inválida");long credit=amount(earned,true);Ledger.require(credit>=0,"El abono no puede ser negativo");LocalData.change(host,d->{JSONObject account=Ledger.find(d.getJSONArray("accounts"),a.getString("id"));JSONObject y=account.optJSONObject("yield");if(y==null)y=new JSONObject();y.put("enabled",r>0).put("annualRate",r);account.put("yield",y);if(credit>0){if(Ledger.find(d.getJSONArray("categories"),"income-yield")==null)d.getJSONArray("categories").put(new JSONObject().put("id","income-yield").put("name","Rendimientos de ahorro").put("type","income").put("emoji","").put("color","#087F79").put("archived",false));d.getJSONArray("transactions").put(NativeSync.transaction("income",credit,a.getString("id"),"","income-yield","Interés abonado","yield",""));}});});}
 static String csv(String s){if(s.matches("^[=+@\\-].*"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 static void export(MainActivity a,boolean csv)throws Exception{if(csv){StringBuilder out=new StringBuilder("\ufeffFecha;Tipo;Monto CLP;Cuenta;Destino;Categoría;Descripción;Estado\r\n");for(JSONObject t:a.transactions())out.append(csv(t.optString("date"))).append(';').append(csv(t.optString("type"))).append(';').append(t.optLong("amount")).append(';').append(csv(a.name("accounts",t.optString("account")))).append(';').append(csv(t.optString("to").isEmpty()?"":a.name("accounts",t.optString("to")))).append(';').append(csv(t.optString("category").isEmpty()?"":a.name("categories",t.optString("category")))).append(';').append(csv(t.optString("note"))).append(';').append(csv(t.optString("status"))).append("\r\n");a.exportContent=out.toString();}else a.exportContent=LocalData.backup(a).toString(2);a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(csv?"text/csv":"application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Bolsillo-"+Ledger.today()+(csv?".csv":".json")),21);}
 static void fileResult(MainActivity a,int req,Intent intent)throws Exception{if(req==21&&a.exportContent!=null){try(OutputStream out=a.getContentResolver().openOutputStream(intent.getData())){if(out==null)throw new IOException("No se pudo abrir el destino");out.write(a.exportContent.getBytes("UTF-8"));}a.exportContent=null;NativeSettings.info(a,"Archivo guardado");}if(req==22){ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(intent.getData())){if(in==null)throw new IOException("No se pudo abrir el archivo");byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){bytes.write(buffer,0,n);Ledger.require(bytes.size()<=20000000,"La copia supera 20 MB");}}JSONObject backup=new JSONObject(bytes.toString("UTF-8"));JSONObject ledger=LocalData.importData(backup);a.confirm("Restaurar copia","La copia contiene "+ledger.getJSONArray("accounts").length()+" cuentas y "+ledger.getJSONArray("transactions").length()+" movimientos. Reemplazará el registro actual. Exporta primero si quieres conservarlo.",()->LocalData.restore(a,backup));}}
}
